// Lo que vis.js le pasa al ctxRenderer de un nodo custom
// https://visjs.github.io/vis-network/docs/network/nodes.html
interface CtxRendererArgs {
  ctx: CanvasRenderingContext2D;
  x: number;
  y: number;
  state: { selected: boolean; hover: boolean };
  style: { size: number; opacity: number; color: string };
  label: string;
}

// Dibuja un rombo
const drawFinDeCarrera = ({
  ctx,
  x,
  y,
  state: { selected, hover },
  style,
  label,
}: CtxRendererArgs) => {
  let r = style.size;
  const drawNode = () => {
    if (selected || hover) {
      r += 3;
    }
    ctx.beginPath();
    const sides = 4;
    const a = (Math.PI * 2) / sides;
    ctx.moveTo(x, y + r);
    for (let i = 1; i < sides; i++) {
      ctx.lineTo(x + r * Math.sin(a * i), y + r * Math.cos(a * i));
    }
    ctx.closePath();
    ctx.save();

    ctx.fillStyle = style.color;
    ctx.strokeStyle = selected || hover ? "black" : "gray";
    ctx.lineWidth = selected || hover ? 3 : 2;
    ctx.globalAlpha = style.opacity;
    ctx.fill();
    ctx.stroke();
    ctx.restore();

    ctx.textAlign = "center";
    const lines = label.split("\n");
    const lineheight = 13;
    let mid = lines.length / 2;
    let fontSize = 12;
    let maxLineWidth = 0;
    for (const line of lines) {
      if (ctx.measureText(line).width > maxLineWidth) {
        maxLineWidth = ctx.measureText(line).width;
      }
    }
    if (maxLineWidth > r * 1.5) {
      fontSize -= 1;
    }
    let boldness = selected || hover ? "bold" : "500";
    ctx.font = `${boldness} ${fontSize}px arial`;
    ctx.fillStyle = selected || hover ? "black" : "";
    lines.forEach((line, i) => {
      ctx.fillText(line, x, y + (i + 0.5 - mid) * lineheight);
    });
  };
  return {
    drawNode,
  };
};

